from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []
    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # check expiry first
            if key in cache:
                v, wt = cache[key]
                if t >= wt + ttl:
                    del cache[key]
            if key in cache:
                # update value, move to end (most recently used)
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                # remove any expired entries so capacity check is accurate
                expired_keys = [k for k, (v, wt) in cache.items() if t >= wt + ttl]
                for k in expired_keys:
                    del cache[k]
                if len(cache) >= capacity:
                    # evict least recently used
                    cache.popitem(last=False)
                cache[key] = (value, t)
                cache.move_to_end(key)
        else:
            _, t, key = op
            if key in cache:
                v, wt = cache[key]
                if t >= wt + ttl:
                    del cache[key]
                    results.append(-1)
                else:
                    results.append(v)
                    cache.move_to_end(key)
            else:
                results.append(-1)
    return results

